Looking at the working files, the `AppWindow.vue` already has the URL tracking logic implemented. I need to ensure it properly stores and restores the `lastUrl` from params, and that the `Desktop.vue` properly persists and restores these params through the layout system.

The key issue is that when `dockview` saves/restores layout via `toJSON/fromJSON`, the `params` (including `lastUrl`) need to be preserved. Let me review and update `AppWindow.vue` to make sure the URL tracking is solid.

```vue src/components/windowManager/AppWindow.vue
<script setup>
import Iframe from '../Iframe.vue'
</script>

<template>
  <div class="w-full h-full" :class="loaded ? '' : 'opacity-10'">
    <Iframe
      class="w-full h-full"
      :key="theApp.path"
      :url="currentUrl"
      @loaded="onLoaded"
      @navigated="onNavigated"
    />
  </div>
</template>

<script>
export default {
  name: "AppWindow",
  props: ['app', 'params'],
  data() {
    return {
      loaded: false,
      currentUrl: null
    }
  },
  created() {
    const app = this.theApp
    // Restore last navigated URL from params or fall back to app path
    this.currentUrl = this.params?.lastUrl || this.params?.params?.lastUrl || app?.path
    this.loaded = app?.is_vnc
  },
  computed: {
    theApp() {
      return this.app || this.params?.params?.app || this.params?.app
    },
    tabId() {
      return this.theApp?.tabId
    }
  },
  methods: {
    onLoaded() {
      this.loaded = true
    },
    // Track url changes and persist them in the app params via store
    onNavigated(url) {
      if (!url || url === this.currentUrl) return
      this.currentUrl = url
      this.persistUrl(url)
    },
    // Persist current URL so layout restore can recover it
    persistUrl(url) {
      if (!this.tabId) return
      this.$storex.ui.updateAppParams({
        tabId: this.tabId,
        params: { lastUrl: url }
      })
    }
  }
}
</script>
```

Now update `Desktop.vue` to ensure panel params (including `lastUrl`) are passed back when restoring layout:

```vue src/components/desktop/Desktop.vue
<script setup>
import { DockviewVue } from 'dockview-vue'
import Window from './Window.vue'
import AppWindow from '../windowManager/AppWindow.vue'
import LogViewer from '../LogViewer.vue'

import KnowledgeViewVue from "../../views/KnowledgeView.vue"
import KnowledgeSettingsVue from "../../views/KnowledgeSettings.vue"
import ProfileViewVue from "../../views/ProfileView.vue"
import CodxWelcomeView from "../../views/CodxWelcomeView.vue"
import ProjectSettingsVue from "../../views/ProjectSettings.vue"
import WikiViewVue from "../../views/WikiView.vue"
import DocsViewVue from "../../views/DocsView.vue"
import GlobalSettingsVue from "../../views/GlobalSettings.vue"
import KanbanContainerVue from "../kanban/KanbanContainer.vue"
import Files from "../apps/Files.vue"
import MetricsViewer from "../metrics/MetricsViewer.vue"
import AccountSettings from '../security/AccountSettings.vue'
import FileFinderVue from '../filebrowser/FileFinder.vue'
import ProjectOverview from "../project/ProjectOverview.vue"
import Wall from "../wall/Wall.vue"
import ChatView from '@/views/ChatView.vue'
import Tab from './Tab.vue'
</script>

<template>
  <dockview-vue
    class="dockview-theme-abyss w-full h-full"
    @ready="onReady"
  />
</template>

<script>
const STORAGE_KEY = 'dockview-layout'

export default {
  name: 'Desktop',
  components: {
    'dockview-vue': DockviewVue,
    'window': Window,
    'app-window': AppWindow,
    'log-viewer': LogViewer,
    'knowledge': KnowledgeViewVue,
    'knowledge_settings': KnowledgeSettingsVue,
    'profiles': ProfileViewVue,
    'home': CodxWelcomeView,
    'settings': ProjectSettingsVue,
    'wiki': WikiViewVue,
    'docs': DocsViewVue,
    'global-settings': GlobalSettingsVue,
    'tasks': KanbanContainerVue,
    'files': Files,
    'metrics': MetricsViewer,
    'account': AccountSettings,
    'file-finder': FileFinderVue,
    'projects': ProjectOverview,
    'activity': Wall,
    'chat': ChatView,
    tabComponent: Tab
  },
  props: {
    storageKey: {
      type: String,
      default: STORAGE_KEY
    }
  },
  data() {
    return {
      dockviewApi: null,
      registeredComponents: {
        'window': Window,
        'app-window': AppWindow,
      },
      layoutRestored: false
    }
  },
  computed: {
    apps() {
      const { openApps } = this.$ui
      return Object.values(openApps)
    },
    panelTabIds() {
      return this.dockviewApi?.panels.map(p => p.id)
    },
    uiReady() {
      return this.$ui.uiReady
    }
  },
  watch: {
    apps(newVal) {
      const { panelTabIds } = this
      newVal
        .filter(({ tabId }) => !panelTabIds.includes(tabId))
        .forEach(app => this.addAppPanel(app))
      if (!newVal.length) {
        this.init()
      }
    },
    uiReady() {
      this.restoreLayout()
    }
  },
  methods: {
    init() {
      if (!this.panelTabIds.length) {
        this.$ui.showTab('home')
      }
    },
    addAppPanel(app) {
      if (!app?.tabId) return
      const component = app.component || 'app-window'
      const renderer = 'always'
      this.addPanel({
        id: app.tabId,
        title: app.name,
        component,
        renderer,
        params: {
          ...app.params || {},
          app
        }
      })
    },
    onReady(event) {
      this.dockviewApi = event.api
      this.restoreLayout()
      this.dockviewApi.onDidAddPanel(this.onAddPanel.bind(this))
      this.dockviewApi.onDidRemovePanel(this.onRemovePanel.bind(this))
      this.dockviewApi.onDidLayoutChange(this.saveLayout.bind(this))
    },
    onAddPanel() {
      this.saveLayout()
    },
    onRemovePanel(panel) {
      this.$ui.closeApp(panel.params.app)
      this.saveLayout()
    },
    addPanel({ id, title, component = 'window', position, params, renderer }) {
      if (!this.dockviewApi) return
      if (!this.dockviewApi.panels.find(p => p.id === id)) {
        this.dockviewApi.addPanel({
          id,
          title,
          component,
          position,
          renderer,
          params: {
            ...params,
            tabName: title,
          },
          tabComponent: 'tabComponent'
        })
      }
    },
    removePanel(id) {
      if (!this.dockviewApi) return
      const panel = this.dockviewApi.getPanel(id)
      panel && this.dockviewApi.removePanel(panel)
    },
    registerComponent(name, component) {
      this.registeredComponents = {
        ...this.registeredComponents,
        [name]: component
      }
    },
    saveLayout() {
      if (!this.dockviewApi) return null
      // Merge latest app params (including lastUrl) into layout before saving
      const layout = this.dockviewApi.toJSON()
      this.mergeAppParamsIntoLayout(layout)
      localStorage.setItem(this.storageKey, JSON.stringify(layout))
      return layout
    },
    // Inject current store params into serialized layout panels so lastUrl is persisted
    mergeAppParamsIntoLayout(layout) {
      const { openApps } = this.$ui
      if (!layout?.panels) return
      Object.entries(layout.panels).forEach(([panelId, panelData]) => {
        const app = openApps[panelId]
        if (!app?.params) return
        if (!panelData.params) panelData.params = {}
        // Merge store params (e.g. lastUrl) into serialized panel params
        panelData.params = {
          ...panelData.params,
          ...app.params
        }
      })
    },
    restoreLayout(layout = null) {
      if (this.layoutRestored) return true
      if (!this.dockviewApi || !this.uiReady) return false
      try {
        const data = layout || JSON.parse(localStorage.getItem(this.storageKey))
        if (!data) return false
        this.dockviewApi.fromJSON(data)
        this.dockviewApi.panels.forEach(panel => {
          if (panel.params.chat) {
            this.$chats.reloadChat(panel.params.chat)
          }
          // Restore app with persisted params (including lastUrl)
          const appWithParams = {
            ...panel.params.app,
            params: {
              ...panel.params.app?.params,
              // Carry over top-level params like lastUrl into app params
              lastUrl: panel.params.lastUrl || panel.params.app?.params?.lastUrl
            }
          }
          this.$ui.showApp(appWithParams)
        })
        this.init()
        this.layoutRestored = true
      } catch (e) {
        console.warn('Failed to restore dockview layout:', e)
        return false
      }
    },
    clearSavedLayout() {
      localStorage.removeItem(this.storageKey)
      this.$emit('layout-cleared')
    },
    getLayout() {
      return this.dockviewApi ? this.dockviewApi.toJSON() : null
    }
  },
  expose: [
    "addPanel",
    "removePanel",
    "registerComponent",
    "saveLayout",
    "restoreLayout",
    "clearSavedLayout",
    "getLayout"
  ]
}
</script>

